from itertools import combinations

MAX_ATTEMPTS = 200

def _cross(a, b, c):
    return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])

def _digit_runs(text):
    runs = set()
    current = ""
    for ch in text:
        if ch.isdigit():
            current += ch
        elif current:
            runs.add(current)
            current = ""
    if current:
        runs.add(current)
    return runs

def _strictly_inside(p, a, b, c):
    s1 = _cross(a, b, p)
    s2 = _cross(b, c, p)
    s3 = _cross(c, a, p)
    return (s1 > 0 and s2 > 0 and s3 > 0) or (s1 < 0 and s2 < 0 and s3 < 0)

def generate(seed):
    rng = random.Random(seed)
    n = rng.randint(5, 7)
    points = []
    while len(points) < n:
        p = (rng.randint(-15, 15), rng.randint(-15, 15))
        if p in points or any(_cross(a, b, p) == 0 for a, b in combinations(points, 2)):
            continue
        points.append(p)
    answer = min(abs(_cross(points[i], points[j], points[k])) for i, j, k in combinations(range(n), 3))
    point_text = ", ".join(f"({x}, {y})" for x, y in points)
    if str(answer) in _digit_runs(point_text) | {str(n)}:
        continue
    check = None
    for i, j, k in combinations(range(n), 3):
        a, b, c = points[i], points[j], points[k]
        if any(_strictly_inside(points[r], a, b, c) for r in range(n) if r not in (i, j, k)):
            continue
        area2 = abs(_cross(a, b, c))
        if check is None or area2 < check:
            check = area2
    assert check is not None
    assert answer == check, f"answer={answer} check={check}"
    problem = (
        f"Let S be the following set of {n} points in the plane, no three "
        f"of which are collinear: {point_text}. Call a triangle admissible "
        f"if its three vertices belong to S and no other point of S lies "
        f"strictly inside it. Over all admissible triangles, find the "
        f"minimum possible value of twice the area. State only the integer."
    )
    return problem, str(answer)

