def _is_prime(n):
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2

    d = 3
    while d * d <= n:
        if n % d == 0:
            return False
        d += 2

    return True

WITNESS_SEARCH = 400

def generate(seed):
    rng = random.Random(seed)

    primes = [
        p for p in range(5, 40)
        if _is_prime(p)
    ]
    p = rng.choice(primes)

    answer = p + 1

    check = None

