                witness = d
                break

        if witness is None:
            check = index
            break

    assert check is not None
    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Let \( p = {p} \). For each positive integer \( d \), define an infinite "
        f"sequence by \( a_1 = p \) and \( a_{n+1} = a_n + d \) for every \( n \geq 1 \). "
        f"Find the smallest index \( N \) such that \( a_N \) is composite for every choice "
        f"of \( d \). State only the integer."
    )

