    return (
        (b[0] - a[0]) * (c[1] - a[1])
        - (b[1] - a[1]) * (c[0] - a[0])
    )

def _digit_runs(text):
    runs = set()
    current = ""

    for ch in text:
        if ch.isdigit():
            current += ch
        elif current:
            runs.add(current)
            current = ""

    if current:
        runs.add(current)

    return runs

def _strictly_inside(p, a, b, c):
    s1 = _cross(a, b, p)
    s2 = _cross(b, c, p)
    s3 = _cross(c, a, p)

    return (
        (s1 > 0 and s2 > 0 and s3 > 0)
        or (s1 < 0 and s2 < 0 and s3 < 0)
    )

def generate(seed):
    rng = random.Random(seed)

    n = rng.randint(4, 6)

    for _ in range(MAX_ATTEMPTS):
        points = []

        while len(points) < n:
            p = (
                rng.randint(-10, 10),
                rng.randint(-10, 10),
            )

            if p in points:
                continue

            if any(
                _cross(a, b, p) == 0
                for a, b in combinations(points, 2)
            ):
                continue

            points.append(p)

        answer = min(
            abs(_cross(points[i], points[j], points[k]))
            for i, j, k in combinations(range(n), 3)
        )

        point_text = ", ".join(
            f"({x}, {y})"
            for x, y in points
        )

        if str(answer) in _digit_runs(point_text) | {str(n)}:
            continue

        break
    else:
        raise ValueError("no point set whose answer stays out of the statement")

    check = None

    for i, j, k in combinations(range(n), 3):
        a = points[i]
        b = points[j]
        c = points[k]

        if any(
